const ruText=value=>{const raw=String(value??''),lead=raw.match(/^\s*/)?.[0]||'',trail=raw.match(/\s*$/)?.[0]||'',core=raw.slice(lead.length,raw.length-trail.length);let out=RU[core]||core;out=out.replace(/^(Good morning|Good afternoon|Good evening),$/,greeting=>`${RU[greeting.slice(0,-1)]},`).replace(/^(\d+) of (\d+) required stages finished$/,(_,a,b)=>`${a} из ${b} обязательных этапов завершено`).replace(/^(\d+) left$/,(_,n)=>`Осталось: ${n}`).replace(/^(\d+) open items$/,(_,n)=>`Открыто: ${n}`).replace(/^(\d+) items remaining$/,(_,n)=>`Осталось пунктов: ${n}`).replace(/^(\d+) files$/,(_,n)=>`Файлов: ${n}`).replace(/^(\d+) uploaded$/,(_,n)=>`Загружено: ${n}`).replace(/^(\d+)% completed$/,(_,n)=>`Завершено: ${n}%`).replace(/^(Photo|Video) · (\d+) uploaded(?: · N\/A (\w+))?$/,(_,kind,n,status)=>`${kind==='Photo'?'Фото':'Видео'} · Загружено: ${n}${status?` · Н/Д ${RU[status[0].toUpperCase()+status.slice(1)]||status}`:''}`).replace(/^(\S.+) · (installation|repair|punch list)$/i,(_,code,type)=>`${code} · ${RU[type.toLowerCase()]||type}`).replace(/^(.+) · STAGE (\d+)$/,(_,code,n)=>`${code} · ЭТАП ${n}`).replace(/^STAGE (\d+)$/,(_,n)=>`ЭТАП ${n}`).replace(/^Select (.+)$/,(_,label)=>`Выбрать: ${RU[label]||label}`).replace(/^(.+) \((image|video)\)$/,(_,label,kind)=>`${RU[label]||label} (${RU[kind]||kind})`).replace(/^PM feedback:\s*/, 'Комментарий менеджера: ').replace(/^Video evidence:\s*/, 'Видеоматериал: ');return lead+out+trail;};
function localizeRoot(root=document){if(typeof document.createTreeWalker!=='function')return;const walker=document.createTreeWalker(root,4);const nodes=[];while(walker.nextNode())nodes.push(walker.currentNode);for(const node of nodes){if(!['SCRIPT','STYLE'].includes(node.parentElement?.tagName))node.nodeValue=ruText(node.nodeValue);}for(const el of root.querySelectorAll?.('[placeholder],[title],[aria-label]')||[]){for(const name of ['placeholder','title','aria-label'])if(el.hasAttribute(name))el.setAttribute(name,ruText(el.getAttribute(name)));}}
